function ScanCardDeletionDialog({otpRequired=true,permanent=false,entry=false,target,targets,kind,batchName,onClose,onRequest,onDelete}){
 const dialog=useRef(null),pending=useRef(false);
 const [reason,setReason]=useState(''),[approved,setApproved]=useState(false),[request,setRequest]=useState(null),[otp,setOtp]=useState(''),[working,setWorking]=useState(false),[error,setError]=useState('');
 const multiple=Boolean(targets),count=targets?.length||1,savedCount=targets?.filter(card=>card.status==='posted').length||0;
 const approval=multiple?scanDeletionApproval(targets)+(entry?' · entire scan entry':''):'Approve deletion of card '+target.id+' revision '+target.revision;
 const dismiss=()=>{if(!pending.current)onClose()};
 useEffect(()=>{const node=dialog.current;if(node&&!node.open)node.showModal();return()=>{if(node?.open)node.close()}},[]);
 const send=async()=>{
  if(pending.current||!reason.trim()||!approved||request)return;
  pending.current=true;setWorking(true);setError('');
  try{const result=await onRequest({reason:reason.trim(),approval});if(!result?.requestId)throw Error('WhatsApp OTP could not be requested. No card was deleted.');setRequest(result)}catch(e){setError(e.message)}finally{pending.current=false;setWorking(false)}
 };
 const confirm=async()=>{
  if(pending.current||!reason.trim()||!approved||(otpRequired&&(!request||!/^\d{6}$/.test(otp))))return;
  pending.current=true;setWorking(true);setError('');
  try{await onDelete(otpRequired?{requestId:request.requestId,otp,approval}:{approval,reason:reason.trim(),revision:target.revision})}catch(e){setError(e.message)}finally{pending.current=false;setWorking(false)}
 };
 return <dialog ref={dialog} className="scan-card-deletion-dialog" aria-labelledby="scan-card-deletion-title" onCancel={event=>{event.preventDefault();dismiss()}}>
  <header><div><small>{kind==='vehicle'?'VLB · Trip card':'ELB · Job card'}</small><h2 id="scan-card-deletion-title">{entry?'Delete this sub-batch ('+count+' cards)?':multiple?'Delete '+count+' selected cards?':'Delete card '+target.ordinal+'?'}</h2></div><button type="button" aria-label="Close card deletion" disabled={working} onClick={dismiss}>× Close</button></header>
  <div className="scan-card-deletion-content">
   {multiple&&<div className="scan-group-deletion-preview"><table><thead><tr><th>Card</th><th>Card ID / revision</th><th>File</th><th>Date / location / door</th></tr></thead><tbody>{targets.map(card=><tr key={card.id}><td>{card.ordinal}</td><td>{card.id} · {card.revision}</td><td>{card.filename}</td><td>{[card.draft?.bookDate,card.draft?.location,card.draft?.doorText].filter(Boolean).join(' · ')}</td></tr>)}</tbody></table></div>}
   <dl>{[['Card ID',target.id],['Revision',target.revision],['Batch',batchName||target.batch_id],['Batch ID',target.batch_id],['File',target.filename],['Date',target.draft?.bookDate],['Location',target.draft?.location],['Door',target.draft?.doorText]].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value||'Not recorded'}</dd></div>)}</dl>
   <div className="scan-card-deletion-impact"><p><strong>Impact:</strong> {entry?'Permanently removes this scan entry and its '+count+' cards, including '+savedCount+' saved VLB record(s). Other scan entries and the operational batch stay in place. The VLB batch must be open for changes.':permanent?'Permanently removes this PDF, the selected scan cards, and any VLB records saved from them. The parent batch and other scan entries stay unchanged. If PDFs were previously added to this entry with Addon, review the full card list before continuing.':multiple?'Removes only the selected unsaved cards, extracted values and access to their scans from this entry. All selected cards must still match this preview. Storage/backups may retain original scans.':'Removes this unsaved card, extracted values and original scan.'} {!permanent&&'Unsaved edits will be lost. Other cards stay unchanged.'}</p><p><strong>Recovery:</strong> No application restore. Upload the original again if needed. External backups may retain copies.</p></div>
   <label className="scan-card-deletion-field">Reason for deletion<textarea value={reason} maxLength={2000} disabled={working||Boolean(request)} onChange={event=>setReason(event.target.value)} placeholder="Explain why this card should be deleted"/></label>
   <label className="scan-card-deletion-approval"><input type="checkbox" checked={approved} disabled={working||Boolean(request)} onChange={event=>setApproved(event.target.checked)}/><span>I approve deletion of {multiple?'only the '+count+' selected cards listed above':'only card '+target.ordinal+' shown above'}, including its extracted values and original scan.</span></label>
   {request&&<div className="scan-card-deletion-otp"><p role="status">WhatsApp OTP sent to <strong>{request.recipient}</strong>. Valid for {request.expiresInMinutes||10} minutes. No card has been deleted yet.</p><label className="scan-card-deletion-field">WhatsApp OTP<input type="text" inputMode="numeric" autoComplete="one-time-code" maxLength={6} value={otp} disabled={working} onChange={event=>setOtp(event.target.value.replace(/\D/g,''))} placeholder="6-digit code"/></label></div>}
   {error&&<p className="scan-error" role="alert">{error}</p>}
  </div>
  <footer><button type="button" disabled={working} onClick={dismiss}>Cancel</button>{!otpRequired?<button type="button" className="scan-card-deletion-confirm" disabled={working||!approved||!reason.trim()} onClick={confirm}>{working?'Deleting…':multiple?'Delete '+count+' selected cards':'Delete card'}</button>:request?<button type="button" className="scan-card-deletion-confirm" disabled={working||!approved||!/^\d{6}$/.test(otp)} onClick={confirm}>{working?'Verifying…':multiple?'Verify OTP and delete '+count+' cards':'Verify OTP and delete card'}</button>:<button type="button" className="scan-card-deletion-confirm" disabled={working||!approved||!reason.trim()} onClick={send}>{working?'Sending OTP…':'Approve and send WhatsApp OTP'}</button>}</footer>
 </dialog>;
}



